/*
 * Phrase Forge (offline). Rule-based rewrites that keep the user's meaning.
 * Clear and Commanding are generated by deterministic rules.
 * Vivid needs a concrete detail only the speaker knows, so we generate a scaffold and never invent facts.
 */
(function (root) {
  'use strict';

  var WORDY = [
    [/\bin order to\b/gi, 'to'],
    [/\bdue to the fact that\b/gi, 'because'],
    [/\bowing to the fact that\b/gi, 'because'],
    [/\bat this point in time\b/gi, 'now'],
    [/\bat the present time\b/gi, 'now'],
    [/\bin the event that\b/gi, 'if'],
    [/\bfor the purpose of\b/gi, 'for'],
    [/\bwith regard to\b/gi, 'about'],
    [/\bin regards? to\b/gi, 'about'],
    [/\ba large number of\b/gi, 'many'],
    [/\bthe majority of\b/gi, 'most'],
    [/\bhas the ability to\b/gi, 'can'],
    [/\bis able to\b/gi, 'can'],
    [/\bmake a decision\b/gi, 'decide'],
    [/\bcome to a conclusion\b/gi, 'conclude'],
    [/\bgive consideration to\b/gi, 'consider'],
    [/\bin spite of the fact that\b/gi, 'although'],
    [/\bon a daily basis\b/gi, 'daily'],
    [/\bfuture plans\b/gi, 'plans'],
    [/\bend result\b/gi, 'result'],
    [/\brevert back\b/gi, 'reply'],
    [/\breturn back\b/gi, 'return'],
    [/\brepeat again\b/gi, 'repeat'],
    [/\bdiscuss about\b/gi, 'discuss']
  ];
  var HEDGE_STRIP = [
    /\b(um+|uh+|er+|erm|ah+)\b,?\s*/gi,
    /\b(you know|i mean|basically|literally|actually),?\s*/gi,
    /\bi (just )?(think|guess|feel like|suppose|believe) (that )?/gi,
    /\b(maybe|perhaps|probably|possibly|hopefully|somewhat)\b,?\s*/gi,
    /\b(sort of|kind of|a little bit|a bit)\b\s*/gi,
    /\bjust\b\s*/gi,
    /\bsomehow\b\s*/gi,
    /,?\s*\b(or something|if that makes sense|does that make sense)\b/gi,
    /\btry to\b\s*/gi,
    /\breally\b\s*/gi,
    /\bvery\b\s*/gi
  ];

  function tidy(s) {
    s = s.replace(/\s+/g, ' ').replace(/\s+([,.!?])/g, '$1').replace(/,\s*,/g, ',').replace(/^[,\s]+/, '').trim();
    s = s.replace(/\b(\w+) \1\b/gi, '$1');
    if (s && !/[.!?]$/.test(s)) s += '.';
    return s.charAt(0).toUpperCase() + s.slice(1);
  }

  function clear(text) {
    var s = ' ' + (text || '') + ' ';
    HEDGE_STRIP.forEach(function (re) { s = s.replace(re, ''); });
    WORDY.forEach(function (p) { s = s.replace(p[0], p[1]); });
    s = s.replace(/\bshould probably\b/gi, 'should');
    s = s.replace(/\bmight want to\b/gi, 'should');
    s = s.replace(/\bcould maybe\b/gi, 'could');
    return tidy(s);
  }

  function commanding(text) {
    var s = clear(text);
    var notes = [];
    var before = s;
    s = s.replace(/^we should\b/i, 'We will');
    s = s.replace(/^i would like to\b/i, 'I will');
    s = s.replace(/^i want to\b/i, 'I will');
    s = s.replace(/^we could\b/i, 'Let\'s');
    s = s.replace(/^we need to\b/i, 'Our priority is to');
    s = s.replace(/^it would be good to\b/i, 'We will');
    s = s.replace(/^it might be worth\b/i, 'Let\'s try');
    s = s.replace(/\bwe should\b/gi, 'we will');
    s = s.replace(/\bcan we\b/gi, 'let\'s');
    s = s.replace(/\?$/, '.');
    if (s === before && !/^(we will|let's|i will|our priority)/i.test(s)) {
      s = 'Here is my position: ' + s.charAt(0).toLowerCase() + s.slice(1);
    }
    if (/\bwill\b/i.test(s) && !/\b(by|this|next|before)\s+(monday|tuesday|wednesday|thursday|friday|week|month|quarter|year|\w+day)\b/i.test(s)) {
      notes.push('Commanding lines usually name a deadline or owner. Add one only if it is true: "…by [date]".');
    }
    return { text: tidy(s), notes: notes };
  }

  function vivid(text) {
    var base = clear(text);
    return {
      text: base.replace(/\.$/, '') + ' — for example, [a real person, moment or number].',
      scaffold: [
        'Who is affected? Name a person or role: "a customer in Pune", "our newest hire".',
        'What does it look like? Describe one scene: "the queue at 9 a.m.", "the report nobody opens".',
        'How much? Use a number you actually know: "three days", "one in five".',
        'What is it like? An everyday comparison: "like a traffic jam that never clears".'
      ],
      placeholder: true
    };
  }

  function forge(text) {
    var c = clear(text);
    var cmd = commanding(text);
    var v = vivid(text);
    var origWords = (text || '').split(/\s+/).filter(Boolean).length;
    var clearWords = c.split(/\s+/).filter(Boolean).length;
    return {
      original: text,
      clear: { text: c, why: clearWords < origWords ? 'Removed ' + (origWords - clearWords) + ' words of hedging and padding. Same meaning, less noise.' : 'Already lean — tightened punctuation only.' },
      commanding: { text: cmd.text, why: 'Direct and decisive: states the position as a decision, not a wish.', notes: cmd.notes },
      vivid: { text: v.text, why: 'Concrete details make ideas memorable — but only you know the real ones. Fill the brackets with something true.', scaffold: v.scaffold, placeholder: true }
    };
  }

  var api = { forge: forge, clear: clear, commanding: commanding, vivid: vivid };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else root.Forge = api;
})(typeof window !== 'undefined' ? window : this);
